    def test_classify_character_names(self):
        self.assertEqual(classify_character("\u4e00"), "big5F")
        self.assertEqual(classify_character("\u4e02"), "cjk")
        self.assertEqual(classify_character("\u3400"), "cjkExtA")
        self.assertEqual(classify_character("\ue000"), "pua")
        self.assertEqual(classify_character("\u9feb"), "cjkOther")
        self.assertEqual(classify_character("\u3105"), "bopomofo")
        self.assertEqual(classify_character("\u02ca"), "bopomofoTone")
        # Big5 symbol codes occur on CJK code points such as 兙 (U+5159).
        self.assertEqual(classify_character("\u5159"), "big5S")

    def test_rare_order_names_are_tiered_rare(self):
        self.assertEqual(len(RARE_ORDER), len(set(RARE_ORDER)))
        self.assertEqual(
            {name for name, tier in TIER_BY_NAME.items()
             if tier is CharacterTier.RARE},
            set(RARE_ORDER))
        for name in RARE_ORDER:
            self.assertIs(TIER_BY_NAME[name], CharacterTier.RARE)
        for name in ("bopomofo", "cjk", "big5F", "big5LF"):
            self.assertIs(TIER_BY_NAME[name], CharacterTier.COMMON)
        self.assertIs(TIER_BY_NAME["big5Other"], CharacterTier.OTHER)
        self.assertIs(TIER_BY_NAME["big5S"], CharacterTier.COMMON)
        self.assertIs(TIER_BY_NAME["bopomofoTone"], CharacterTier.COMMON)


